        // assert that either the call reverted (hash unchanged) or the call succeeded
        // and hash equals _hash. Because the test contract is not the depositor, only
        // the first disjunct is reachable, guaranteeing revert and unchanged hash.
        assert(reverted ? c.hash() == beforeHash : c.hash() == _hash);
    }
