        bool reverted;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && c.basefee() == beforeBasefee);
    }

    receive() external payable {}
}

